namespace SprocketExpedition.Core.Encounters;

// Explicit, versioned, platform-independent PRNG. The stream is SplitMix64 and
// the seed is derived only from run seed, round, card index, stream domain and
// AlgorithmVersion. It is never System.Random and never string.GetHashCode, so
// a persisted offer can be regenerated byte-for-byte after restart.
public sealed class StableRandom
{
    public const int AlgorithmVersion = 1;

    private const ulong GoldenGamma = 0x9E3779B97F4A7C15UL;
    private const ulong CardDomain = 0xD1B54A32D192ED03UL;
    private const ulong RoundDomain = 0x94D049BB133111EBUL;

    private ulong _state;

    public StableRandom(long seed, int round, int cardIndex)
        : this(seed, round, cardIndex, CardDomain)
    {
    }

    private StableRandom(long seed, int round, int cardIndex, ulong domain)
    {
        if (round < 1)
        {
            throw new ArgumentOutOfRangeException(
                nameof(round), round, "StableRandom requires a positive round.");
        }

        if (cardIndex < 0)
        {
            throw new ArgumentOutOfRangeException(
                nameof(cardIndex), cardIndex, "StableRandom requires a non-negative card index.");
        }

        ulong mixed = unchecked((ulong)seed);
        mixed = Mix(mixed ^ domain);
        mixed = Mix(mixed ^ unchecked((ulong)(uint)round * GoldenGamma));
        mixed = Mix(mixed ^ unchecked((ulong)(uint)cardIndex * 0xC2B2AE3D27D4EB4FUL));
        mixed = Mix(mixed ^ unchecked((ulong)AlgorithmVersion * 0x14057B7EF767814FUL));
        _state = mixed;
    }

    // A separate stream for round-scoped choices (map rotation) so that adding a
    // card-level draw cannot perturb the map selection. Card streams start at 0.
    public static StableRandom ForRound(long seed, int round) =>
        new(seed, round, 0, RoundDomain);

    public ulong NextUInt64()
    {
        unchecked
        {
            _state += GoldenGamma;
            ulong z = _state;
            z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9UL;
            z = (z ^ (z >> 27)) * 0x94D049BB133111EBUL;
            return z ^ (z >> 31);
        }
    }

    // Rejection sampling removes modulo bias while remaining deterministic.
    public int NextInt(int exclusiveUpperBound)
    {
        if (exclusiveUpperBound <= 0)
        {
            throw new ArgumentOutOfRangeException(
                nameof(exclusiveUpperBound),
                exclusiveUpperBound,
                "Upper bound must be positive.");
        }

        ulong bound = (ulong)exclusiveUpperBound;
        ulong threshold = unchecked(0UL - bound) % bound;
        ulong value;
        do
        {
            value = NextUInt64();
        }
        while (value < threshold);

        return (int)(value % bound);
    }

    private static ulong Mix(ulong z)
    {
        unchecked
        {
            z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9UL;
            z = (z ^ (z >> 27)) * 0x94D049BB133111EBUL;
            return z ^ (z >> 31);
        }
    }
}
